// Hono generic parameters shared by every route/middleware module.
// `Env` (the D1 binding, etc.) is the global ambient type generated by
// `wrangler types` into worker-configuration.d.ts — no import needed.

import type { AuthUser } from './types'

export type AppEnv = {
  Bindings: Env
  Variables: {
    user: AuthUser
    correlationId: string
  }
}
